package cn.xiaoyanjiu.ff14chat;
import android.app.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.webkit.*;import android.widget.*;import org.json.*;
final class BrowserDrawer {
 static final String[] IDS={"accounts","chat","recruit","character","party","stream","fishing","wiki","risingStones","settings","itemSearch","collections","office"};static final String[] LABELS={"账号设置","聊天消息","招募频道","角色信息","队伍信息","游戏画面","鱼糕","灰机Wiki","石之家","应用设置","Omni物品查询","Omni物品收录","国服频道（离线模式）"};
 static final java.util.WeakHashMap<Activity,Dialog> opened=new java.util.WeakHashMap<>();
 static void close(Activity a){Dialog d=opened.remove(a);if(d!=null)d.dismiss();}
 static String asset(Activity a,String name)throws Exception{try(java.io.InputStream in=a.getAssets().open(name)){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}}
 static void navigate(Activity a,Dialog d,String route){if(!java.util.Arrays.asList(IDS).contains(route)||!ChatService.pageEnabled(route))return;d.dismiss();if(route.equals("fishing")||route.equals("wiki")||route.equals("risingStones"))a.startActivity(new Intent(a,route.equals("fishing")?FishingActivity.class:route.equals("wiki")?WikiActivity.class:RisingStonesActivity.class));else a.startActivity(new Intent(a,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("navigatePage",route));a.finish();}
 static void show(Activity a,String current){try{
  close(a);Dialog d=new Dialog(a,android.R.style.Theme_Translucent_NoTitleBar);FrameLayout root=new FrameLayout(a);WebView web=new WebView(a);web.setBackgroundColor(Color.TRANSPARENT);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setTextZoom(100);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}});root.addView(web,new FrameLayout.LayoutParams(-1,-1));
  JSONObject prefs=new JSONObject(a.getSharedPreferences("appearance",0).getString("settings","{}"));String theme=prefs.optString("theme","game");if(!theme.matches("[a-z]+"))theme="game";
  JSONArray rows=new JSONArray(),config=ChatService.pageNavigation;if(config.length()>0){for(int k=0;k<config.length();k++){JSONObject row=config.optJSONObject(k);if(row==null||!row.optBoolean("enabled",true))continue;for(int n=0;n<IDS.length;n++)if(IDS[n].equals(row.optString("id")))rows.put(new JSONObject().put("id",IDS[n]).put("name",LABELS[n]));}}else for(int n=0;n<IDS.length;n++)if(ChatService.pageEnabled(IDS[n]))rows.put(new JSONObject().put("id",IDS[n]).put("name",LABELS[n]));
  String index=asset(a,"index.html");int begin=index.indexOf("<style>")+7,end=index.indexOf("</style>",begin);if(begin<7||end<begin)throw new Exception("主界面样式不可用");String html=asset(a,"browser-drawer.html").replace("__APP_STYLE__",index.substring(begin,end)).replace("__THEME__",theme).replace("__CURRENT_JSON__",JSONObject.quote(current)).replace("__ROWS_JSON__",rows.toString().replace("</","<\\/"));
  web.addJavascriptInterface(new Object(){@JavascriptInterface public void close(){a.runOnUiThread(()->d.dismiss());}@JavascriptInterface public void choose(String route){a.runOnUiThread(()->navigate(a,d,route));}},"Drawer");d.setContentView(root);Window w=d.getWindow();w.setBackgroundDrawableResource(android.R.color.transparent);d.setOnDismissListener(x->{opened.remove(a);web.removeJavascriptInterface("Drawer");web.destroy();});opened.put(a,d);d.show();w.setLayout(-1,-1);
  if(android.os.Build.VERSION.SDK_INT>=30){w.setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets b=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(b.left,b.top,b.right,b.bottom);return WindowInsets.CONSUMED;});root.requestApplyInsets();}else root.setFitsSystemWindows(true);
  web.loadDataWithBaseURL("file:///android_asset/",html,"text/html","UTF-8",null);
 }catch(Exception e){Toast.makeText(a,"无法打开页面导航："+e.getMessage(),Toast.LENGTH_SHORT).show();}}
}
